interface Product {
  id: string;
  price: number;
  inStock: boolean;
}

function buy(item: Product): string {
  return "Buying " + item.id + " for $" + item.price;
}

interface Profile {
  username: string;
  bio?: string;      // might not exist yet
  avatarUrl?: string;
}

const p1: Profile = { username: "roli" };              // fine
const p2: Profile = { username: "roli", bio: "hi" }; // fine

type ID = string | number;
type Status = "todo" | "doing" | "done";

function setStatus(s: Status): void {
  console.log("Status:", s);
}
setStatus("doing");  // fine
// setStatus("nap"); // ERROR: not a valid status

// Object shape → interface
interface Task { title: string; done: boolean; }

// Union → type alias
type Filter = "all" | "active" | "done";

// Function signature → type alias
type ClickHandler = (id: string) => void;

interface User {
  readonly id: string;
  name: string;
}

interface Admin extends User {
  role: string;
}

const a: Admin = { id: "u1", name: "Roli", role: "owner" };
// a.id = "u2"; // ERROR: readonly

interface Comment {
  author: User;
  text: string;
}

interface Post {
  title: string;
  comments: Comment[];
}
